//! Phase 6: C-ABI Host Interface & Auto-Generated `.h` Header Emitter.
//! Generates C99/C++ compatible SoA descriptors and `aerotick_step` FFI signatures
//! for Godot 4 (GDExtension), Unreal Engine, Rust, and bare-metal flight controllers.

use aerotick_mir::{MirProgram, MirType};

/// 32-byte aligned 4-lane SIMD vector matching the C-ABI `AeroVec3Simd4` layout.
#[repr(C, align(32))]
#[derive(Debug, Clone, Copy, Default, PartialEq)]
pub struct AeroVec3Simd4 {
    pub x: f64,
    pub y: f64,
    pub z: f64,
    pub pad: f64,
}

/// Emits a self-contained C/C++ header (`aerotick.h`) for the compiled `MirProgram`.
pub fn emit_c_header(mir: &MirProgram) -> String {
    let mut lines = vec![
        "/* Auto-generated by AeroTick Compiler (aeroc) — C-ABI Host Interface */".to_string(),
        "#pragma once".to_string(),
        "#include <stddef.h>".to_string(),
        "#include <stdint.h>".to_string(),
        String::new(),
        "#ifdef __cplusplus".to_string(),
        "extern \"C\" {".to_string(),
        "#endif".to_string(),
        String::new(),
        "/* 32-byte aligned 4-lane SIMD vector (x, y, z, _pad) */".to_string(),
        "typedef struct __attribute__((aligned(32))) {".to_string(),
        "    double x;".to_string(),
        "    double y;".to_string(),
        "    double z;".to_string(),
        "    double _pad;".to_string(),
        "} AeroVec3Simd4;".to_string(),
        String::new(),
    ];

    for layout in &mir.layouts {
        lines.push(format!(
            "/* Structure-of-Arrays (SoA) descriptor for state '{}' ({} bytes/entity) */",
            layout.state_name, layout.total_bytes_per_entity
        ));
        lines.push("typedef struct {".to_string());
        for f in &layout.fields {
            match f.mir_type {
                MirType::Vec3Simd4 | MirType::QuatSimd4 => {
                    lines.push(format!("    AeroVec3Simd4* {}; /* 32B aligned */", f.name));
                }
                _ => {
                    lines.push(format!("    double* {}; /* 8B aligned */", f.name));
                }
            }
        }
        lines.push(format!("}} {}_SoA;", layout.state_name));
        lines.push(String::new());
    }

    for sys in &mir.systems {
        lines.push(format!(
            "void aerotick_step_{}(const {}_SoA* __restrict prev, {}_SoA* __restrict next, size_t count, double {});",
            sys.name.to_lowercase(),
            sys.state_name,
            sys.state_name,
            sys.dt_param
        ));
    }

    lines.push(String::new());
    lines.push("#ifdef __cplusplus".to_string());
    lines.push("}".to_string());
    lines.push("#endif".to_string());
    lines.join("\n")
}

#[cfg(test)]
mod tests {
    use super::*;
    use aerotick_lexer::lex;
    use aerotick_mir::lower_to_mir;
    use aerotick_parser::parse;
    use aerotick_sema::analyze;

    #[test]
    fn generates_c_header_for_reference_body() {
        let src = include_str!("../../../examples/reference_body.aero");
        let (tokens, _) = lex(src);
        let (ast, _) = parse(&tokens, src.len());
        let (hir, _) = analyze(&ast.expect("ast"));
        let mir = lower_to_mir(&hir);
        let header = emit_c_header(&mir);
        assert!(header.contains("AeroVec3Simd4"));
        assert!(header.contains("Body_SoA"));
        assert!(header.contains("aerotick_step_integrate"));
    }
}
